import { NextRequest, NextResponse } from 'next/server';
import createMiddleware from 'next-intl/middleware';
import { routing } from './i18n/routing';

const intlMiddleware = createMiddleware(routing);

// Pages that exist outside [locale] routing — don't redirect them.
// Includes Next.js metadata image routes generated by icon.tsx / apple-icon.tsx
const NON_LOCALE_PATHS = ['/contact', '/icon', '/apple-icon', '/opengraph-image'];

export default function middleware(request: NextRequest) {
  const pathname = request.nextUrl.pathname;

  // Skip locale redirect for pages that live at root (not under [locale])
  if (NON_LOCALE_PATHS.some(p => pathname === p || pathname.startsWith(p + '/'))) {
    return NextResponse.next();
  }

  return intlMiddleware(request);
}

export const config = {
  /* /api exclu : le matcher attrapait /api/contact et next-intl le
     redirigeait vers /fr/api/contact — une page HTML 200. Le formulaire de
     contact affichait « envoyé » pendant que le handler n'était jamais
     exécuté : chaque lead du site partait au néant. */
  matcher: ['/((?!api|_next|_vercel|.*\\..*).*)']
};
